var d = msg.payload;
var required = ["device_id","co2_ppm","temperature_c","humidity_pct","pressure_hpa","light_lux","sound_level_adc"];
var missing = required.filter(function(k){ return d[k] === undefined; });
if (missing.length > 0) { node.warn("Missing: " + missing.join(", ")); return null; }
if (d.co2_ppm < 0 || d.co2_ppm > 5000) { node.warn("CO2 out of range"); return null; }
if (d.temperature_c < -40 || d.temperature_c > 85) { node.warn("Temp out of range"); return null; }
if (d.humidity_pct < 0 || d.humidity_pct > 100) { node.warn("Humidity out of range"); return null; }
d.timestamp = new Date().toISOString();
d.gateway_id = "node-red-gw-01";
d.source = "uart";
if (d.sound_peak_adc === undefined) d.sound_peak_adc = d.sound_level_adc;
if (d.sound_rms_adc === undefined) d.sound_rms_adc = d.sound_level_adc;
if (d.sound_event === undefined) d.sound_event = false;
msg.payload = d;
return msg;

var MAX = 6;
var buffer = flow.get("readingBuffer") || [];
buffer.push(msg.payload);
if (buffer.length >= MAX) {
    var batch = buffer.splice(0, MAX);
    flow.set("readingBuffer", buffer);
    var seq = (flow.get("seq") || 0) + 1;
    flow.set("seq", seq);
    msg.payload = { gateway_id: "node-red-gw-01", sent_at: new Date().toISOString(), sequence: seq, readings: batch };
    node.status({fill:"green",shape:"dot",text:batch.length+" sent (seq "+seq+")"});
    return msg;
} else {
    flow.set("readingBuffer", buffer);
    node.status({fill:"yellow",shape:"ring",text:"buffered: "+buffer.length+"/"+MAX});
    return null;
}

if (msg.statusCode === 200 || msg.statusCode === 201) {
    node.status({fill:"green",shape:"dot",text:"OK "+msg.statusCode});
} else {
    node.warn("Backend error: "+msg.statusCode);
    node.status({fill:"red",shape:"ring",text:"ERR "+msg.statusCode});
}
return msg;
